_COMPRESSED = base64.b85decode(_PAYLOAD)
try:
    _SOURCE = zlib.decompress(_COMPRESSED)
except zlib.error as _decompress_error:
    # The legacy envelope may have an invalid Adler-32 while its DEFLATE
    # stream is intact. Decode only that case; truncated streams still fail.
    if "incorrect data check" not in str(_decompress_error) or len(_COMPRESSED) < 6:
        raise
    _SOURCE = zlib.decompress(_COMPRESSED[2:-4], -zlib.MAX_WBITS)

# Convert the old AI-only registry to the conventional model identifiers.
for _old, _new in (
    (b'"gfs_ai"', b'"gfs"'),
    (b"'gfs_ai'", b"'gfs'"),
    (b'"icon_ai"', b'"icon_dwd"'),
    (b"'icon_ai'", b"'icon_dwd'"),
):
    _SOURCE = _SOURCE.replace(_old, _new)

_SOURCE = _SOURCE.replace(b"GFS-AI / AIGFS", b"GFS / GEV3")
_SOURCE = _SOURCE.replace(b"ICON-AI / AICON", b"ICON / DWD")
_SOURCE = _SOURCE.replace(b"NOAA AIGFS", b"NOAA GFS 0.25")
_SOURCE = _SOURCE.replace(b"DWD AICON", b"DWD ICON Global")
_SOURCE = _SOURCE.replace(b"gfs-ai-skewt-click", b"gfs-skewt-click")
_SOURCE = _SOURCE.replace(b"icon-ai-skewt-click", b"icon-dwd-skewt-click")

# The AIGFS proxy fallback is not valid for conventional GFS. Require its
# published native surface pressure and terrain instead of borrowing AI logic.
_SOURCE = _SOURCE.replace(
    b'if model_key == "gfs" and (not math.isfinite(terrain) or not math.isfinite(psfc)):',
    b'if model_key == "__disabled_ai_fallback__" and (not math.isfinite(terrain) or not math.isfinite(psfc)):',
)

# Install a native ICON/DWD extractor. It accepts DWD hybrid/model-level
# pressure fields and uses actual surface orography; it does not call AICON.
_ICON_DWD_SOURCE = "\ndef extract_icon_dwd_profile(\n    samples: dict[tuple[str, str, str], float],\n    manifest: dict[str, Any],\n    latitude: float,\n    longitude: float,\n) -> tuple[Any, list[dict[str, float]], float, dict[str, Any]]:\n    \"\"\"Build an ICON/DWD profile from native pressure-on-model-level fields.\"\"\"\n    variables = manifest.get(\"variables\") or []\n    pressure_items = [\n        item for item in variables\n        if str(item.get(\"short_name\", \"\")).lower() in {\"pres\", \"p\"}\n        and str(item.get(\"level_type\", \"\")).lower()\n        not in {\"surface\", \"meansea\", \"heightaboveground\", \"heightabovegroundlayer\"}\n    ]\n    preferred = (\"hybrid\", \"hybridlayer\", \"modellevel\", \"generalvertical\", \"generalverticalheight\")\n    available_types = {\n        str(item.get(\"level_type\", \"\")).lower() for item in pressure_items\n    }\n    vertical_type = next((item for item in preferred if item in available_types), None)\n    if vertical_type is None and available_types:\n        vertical_type = sorted(available_types)[0]\n    if vertical_type is None:\n        raise RuntimeError(\"ICON/DWD não publicou pressão em níveis verticais nativos.\")\n\n    pressure_name = \"pres\" if any(\n        str(item.get(\"short_name\", \"\")).lower() == \"pres\"\n        and str(item.get(\"level_type\", \"\")).lower() == vertical_type\n        for item in pressure_items\n    ) else \"p\"\n    levels = sorted({\n        normalise_level(item.get(\"level\"))\n        for item in pressure_items\n        if str(item.get(\"level_type\", \"\")).lower() == vertical_type\n        and str(item.get(\"short_name\", \"\")).lower() == pressure_name\n    }, key=lambda value: float(value))\n\n    def sample(name: str, level: str) -> float:\n        return find_sample(samples, name, vertical_type, level)\n\n    native: list[dict[str, float]] = []\n    for level in levels:\n        p_raw = sample(pressure_name, level)\n        p_units = manifest_units(manifest, pressure_name, vertical_type, level) or \"Pa\"\n        pressure = pressure_hpa(p_raw, p_units)\n        temp_raw = sample(\"t\", level)\n        temp_units = manifest_units(manifest, \"t\", vertical_type, level) or \"K\"\n        temp = temperature_c(temp_raw, temp_units)\n        q = sample(\"q\", level)\n        rh = sample(\"r\", level)\n        dew = dewpoint_from_specific_humidity(q, pressure)\n        if not math.isfinite(dew) and math.isfinite(rh):\n            rh_units = manifest_units(manifest, \"r\", vertical_type, level)\n            dew = dewpoint_from_relative_humidity(temp, rh, rh_units)\n        if math.isfinite(dew) and not math.isfinite(q):\n            vapor = 6.112 * math.exp((17.67 * dew) / (dew + 243.5))\n            mixing = 0.622 * vapor / max(pressure - vapor, 0.1)\n            q = mixing / (1.0 + mixing)\n        u_raw, v_raw = sample(\"u\", level), sample(\"v\", level)\n        u_units = manifest_units(manifest, \"u\", vertical_type, level) or \"m s**-1\"\n        v_units = manifest_units(manifest, \"v\", vertical_type, level) or \"m s**-1\"\n        u, v = wind_kt(u_raw, u_units), wind_kt(v_raw, v_units)\n        if all(math.isfinite(x) for x in (pressure, temp, dew, q, u, v)) and 0 < pressure < 1100:\n            native.append({\n                \"model_level\": float(level),\n                \"pressure_hpa\": pressure,\n                \"temperature_c\": temp,\n                \"dewpoint_c\": min(dew, temp),\n                \"q\": q,\n                \"wind_u_kt\": u,\n                \"wind_v_kt\": v,\n                \"omega_pa_s\": math.nan,\n            })\n    native.sort(key=lambda row: row[\"pressure_hpa\"], reverse=True)\n    if len(native) < 8:\n        raise RuntimeError(\n            f\"ICON/DWD publicou somente {len(native)} níveis verticais utilizáveis; são necessários ao menos 8.\"\n        )\n\n    terrain = math.nan\n    terrain_source = \"\"\n    for short_name, default_units in (\n        (\"orog\", \"m\"), (\"hsurf\", \"m\"), (\"z\", \"m**2 s**-2\"),\n        (\"gh\", \"gpm\"), (\"hgt\", \"m\"),\n    ):\n        raw = find_sample(samples, short_name, \"surface\", 0)\n        units = manifest_units(manifest, short_name, \"surface\", 0) or default_units\n        value = geopotential_height(raw, units)\n        if math.isfinite(value):\n            terrain, terrain_source = value, short_name\n            break\n    if not math.isfinite(terrain):\n        raise RuntimeError(\n            \"ICON/DWD não publicou orografia de superfície (orog/hsurf/z/gh); \"\n            \"o renderizador SPC exige altitude real do terreno.\"\n        )\n\n    psfc = math.nan\n    pressure_source = \"\"\n    for short_name in (\"sp\", \"pres\"):\n        raw = find_sample(samples, short_name, \"surface\", 0)\n        units = manifest_units(manifest, short_name, \"surface\", 0) or \"Pa\"\n        value = pressure_hpa(raw, units)\n        if math.isfinite(value) and 100 < value < 1100:\n            psfc, pressure_source = value, short_name\n            break\n\n    rows: list[dict[str, float]] = []\n    t2 = temperature_c(\n        find_sample(samples, \"2t\", \"heightAboveGround\", 2),\n        manifest_units(manifest, \"2t\", \"heightAboveGround\", 2) or \"K\",\n    )\n    td2 = temperature_c(\n        find_sample(samples, \"2d\", \"heightAboveGround\", 2),\n        manifest_units(manifest, \"2d\", \"heightAboveGround\", 2) or \"K\",\n    )\n    u10 = wind_kt(\n        find_sample(samples, \"10u\", \"heightAboveGround\", 10),\n        manifest_units(manifest, \"10u\", \"heightAboveGround\", 10) or \"m s**-1\",\n    )\n    v10 = wind_kt(\n        find_sample(samples, \"10v\", \"heightAboveGround\", 10),\n        manifest_units(manifest, \"10v\", \"heightAboveGround\", 10) or \"m s**-1\",\n    )\n\n    # Use actual 2-m/10-m fields and surface pressure when all are available.\n    # Otherwise anchor the lowest native model level at the published orography\n    # and explicitly identify that lower-level reference in the metadata.\n    has_surface_obs = all(math.isfinite(x) for x in (psfc, t2, td2, u10, v10))\n    if has_surface_obs and psfc > native[0][\"pressure_hpa\"] + 0.5:\n        rows.append({\n            \"pressure_hpa\": psfc,\n            \"height_m\": terrain,\n            \"temperature_c\": t2,\n            \"dewpoint_c\": min(td2, t2),\n            \"wind_u_kt\": u10,\n            \"wind_v_kt\": v10,\n            \"omega_pa_s\": math.nan,\n        })\n        previous = {\n            \"pressure_hpa\": psfc,\n            \"height_m\": terrain,\n            \"temperature_c\": t2,\n            \"q\": math.nan,\n        }\n        vapor = 6.112 * math.exp((17.67 * td2) / (td2 + 243.5))\n        mixing = 0.622 * vapor / max(psfc - vapor, 0.1)\n        previous[\"q\"] = mixing / (1.0 + mixing)\n    else:\n        previous = None\n        if not math.isfinite(psfc):\n            psfc = native[0][\"pressure_hpa\"]\n            pressure_source = \"menor nível de pressão nativo\"\n    for index, row in enumerate(native):\n        if row[\"pressure_hpa\"] >= psfc - 0.5:\n            continue\n        direct_height = math.nan\n        for short_name, default_units in ((\"gh\", \"gpm\"), (\"z\", \"m**2 s**-2\"), (\"hgt\", \"m\")):\n            raw = sample(short_name, normalise_level(row[\"model_level\"]))\n            units = manifest_units(manifest, short_name, vertical_type, row[\"model_level\"]) or default_units\n            direct_height = geopotential_height(raw, units)\n            if math.isfinite(direct_height):\n                break\n        if math.isfinite(direct_height) and direct_height > terrain + 1.0:\n            row[\"height_m\"] = direct_height\n        elif previous is None:\n            # The lower full model level is the lowest resolvable model datum.\n            row[\"height_m\"] = terrain\n        else:\n            p0, p1 = previous[\"pressure_hpa\"], row[\"pressure_hpa\"]\n            if p1 >= p0:\n                continue\n            t0 = previous[\"temperature_c\"] + 273.15\n            t1 = row[\"temperature_c\"] + 273.15\n            q0 = max(0.0, previous[\"q\"]) if math.isfinite(previous[\"q\"]) else 0.0\n            q1 = max(0.0, row[\"q\"])\n            tv = 0.5 * (\n                t0 * (1.0 + 0.61 * q0) + t1 * (1.0 + 0.61 * q1)\n            )\n            thickness = (287.05 * tv / G) * math.log(p0 / p1)\n            if not math.isfinite(thickness) or thickness <= 0:\n                continue\n            row[\"height_m\"] = previous[\"height_m\"] + thickness\n        rows.append({\n            \"pressure_hpa\": row[\"pressure_hpa\"],\n            \"height_m\": row[\"height_m\"],\n            \"temperature_c\": row[\"temperature_c\"],\n            \"dewpoint_c\": row[\"dewpoint_c\"],\n            \"wind_u_kt\": row[\"wind_u_kt\"],\n            \"wind_v_kt\": row[\"wind_v_kt\"],\n            \"omega_pa_s\": math.nan,\n        })\n        previous = {\n            \"pressure_hpa\": row[\"pressure_hpa\"],\n            \"height_m\": row[\"height_m\"],\n            \"temperature_c\": row[\"temperature_c\"],\n            \"q\": row[\"q\"],\n        }\n\n    rows.sort(key=lambda row: row[\"pressure_hpa\"], reverse=True)\n    clean: list[dict[str, float]] = []\n    for row in rows:\n        if clean and (\n            abs(row[\"pressure_hpa\"] - clean[-1][\"pressure_hpa\"]) < 0.05\n            or row[\"height_m\"] <= clean[-1][\"height_m\"] + 0.5\n        ):\n            continue\n        clean.append(row)\n    if len(clean) < 8:\n        raise RuntimeError(\n            f\"Perfil ICON/DWD insuficiente: somente {len(clean)} níveis válidos após o controle vertical.\"\n        )\n\n    valid_time = parse_utc(manifest.get(\"_active_valid_time\") or manifest.get(\"run_utc\"))\n    sounding = _create_sharppy_profile(clean, latitude, longitude, valid_time)\n    return sounding, clean, terrain, {\n        \"surface_pressure_hpa\": psfc,\n        \"surface_pressure_source\": pressure_source or \"perfil vertical nativo\",\n        \"terrain_reference\": \"orografia nativa do ICON/DWD\",\n        \"terrain_source_field\": terrain_source,\n        \"terrain_label\": f\"Terreno nativo ICON/DWD · {terrain:.0f} m\",\n        \"terrain_is_estimated\": False,\n        \"vertical_reference\": (\n            \"orografia MSL nativa; níveis híbridos com altura geopotencial quando disponível \"\n            \"e integração hidrostática entre níveis\"\n        ),\n        \"grid_latitude\": latitude,\n        \"grid_longitude\": longitude,\n        \"native_model_level_count\": len(clean),\n    }\n\n\n"
_SOURCE = _SOURCE.replace(
    b"def extract_profile(",
    _ICON_DWD_SOURCE.encode("utf-8") + b"\n\ndef extract_profile(",
    1,
)
_SOURCE = _SOURCE.replace(
    b'if model_key == "icon_dwd":\n        return extract_icon_ai_profile(samples, manifest, latitude, longitude)',
    b'if model_key == "icon_dwd":\n        return extract_icon_dwd_profile(samples, manifest, latitude, longitude)',
    1,
)

# Normalize the legacy argparse block. The compressed payload currently contains
# a damaged parser declaration; rebuild this small block instead of relying on
# fragile literal spellings inside the payload.
_MAIN_MARKER = b"def main() -> int:\n"
_ARGS_BOUNDARY = b"    output_dir = args.output_dir.resolve()"
if _MAIN_MARKER not in _SOURCE:
    raise RuntimeError("Runner global Skew-T sem a função main().")
_HEAD, _MAIN_TAIL = _SOURCE.split(_MAIN_MARKER, 1)
if _ARGS_BOUNDARY not in _MAIN_TAIL:
    raise RuntimeError("Bloco de argumentos do runner não pôde ser localizado.")
_PARSER_BLOCK = b"""    parser = argparse.ArgumentParser(
        description="Gera sondagens Skew-T globais para GFS, ICON/DWD e ECMWF IFS."
    )
    parser.add_argument("--model-key", required=True, choices=sorted(MODEL_CONFIG))
    parser.add_argument("--latitude", required=True, type=float)
    parser.add_argument("--longitude", required=True, type=float)
    parser.add_argument("--forecast-hour", required=True, type=int)
    parser.add_argument("--request-id", required=True)
    parser.add_argument("--renderer", required=True, type=Path)
    parser.add_argument("--output-dir", required=True, type=Path)
    args = parser.parse_args()

"""
_SOURCE = _HEAD + _MAIN_MARKER + _PARSER_BLOCK + _MAIN_TAIL[_MAIN_TAIL.index(_ARGS_BOUNDARY):]

# All conventional models must expose real terrain-relative height above ground.
_SOURCE = _SOURCE.replace(
    b'"base_level_is_proxy": model_key in {"gfs", "icon_dwd"},',
    b'"base_level_is_proxy": False,',
)
_SOURCE = _SOURCE.replace(
    b'"height_agl_m": (\n                row["height_m"] - terrain\n                if model_key == "ecmwf_ifs" else None\n            ),\n            "height_reference_m": (\n                row["height_m"] - terrain\n                if model_key != "ecmwf_ifs" else None\n            ),',
    b'"height_agl_m": row["height_m"] - terrain,\n            "height_reference_m": None,',
)
_SOURCE = _SOURCE.replace(
    b"ICON-AI generalVertical pressure levels with hydrostatic relative heights",
    b"ICON/DWD native model-level pressure profile anchored to published surface orography",
)

_REQUIRED = (b"def main", b"MODEL_CONFIG", b'"gfs":', b'"icon_dwd":', b'"ecmwf_ifs":', b"def extract_icon_dwd_profile")
_MISSING = [item.decode("ascii") for item in _REQUIRED if item not in _SOURCE]
if _MISSING:
    raise RuntimeError("Runner convencional incompleto; marcadores ausentes: " + ", ".join(_MISSING))

compile(_SOURCE, __file__ + " [expanded]", "exec")
exec(compile(_SOURCE, __file__ + " [expanded]", "exec"), globals())
